/// Returns `(traceId, spanId, traceFlags)` of the active OpenTelemetry span, if any.
pub(crate) fn active_trace_context() -> Option<(String, String, u8)> {
    use opentelemetry::trace::TraceContextExt;
    let cx = opentelemetry::Context::current();
    let span = cx.span();
    let sc = span.span_context();
    if !sc.is_valid() {
        return None;
    }
    Some((
        sc.trace_id().to_string(),
        sc.span_id().to_string(),
        sc.trace_flags().to_u8(),
    ))
}
